using namespace KiteWindHttp;
using KiteWindDisplay::MAX_SPOTS;

static std::vector<std::string> uuids(size_t count) {
  std::vector<std::string> out;
  char text[37];
  for (size_t i = 0; i < count; i++) {
    std::snprintf(text, sizeof(text), "%08zx-0000-4000-8000-%012zx", i, i * 7919);
    out.push_back(text);
  }
  return out;
}

// Full 51-UUID target: 51 * 36 + 50 commas = 1886 bytes of ID list.
static void testRequestBuilder() {
  std::vector<std::string> ids = uuids(MAX_SPOTS);
  const char* pointers[MAX_SPOTS];
  for (size_t i = 0; i < MAX_SPOTS; i++) pointers[i] = ids[i].c_str();
  std::vector<char> out(KiteWindDisplay::requestCapacity(MAX_SPOTS)), scratch(KiteWindDisplay::responseCapacity(MAX_SPOTS));
  size_t length = buildRequest(out.data(), out.size(), scratch.data(), scratch.size(), pointers, MAX_SPOTS,
                               "api.kustgloed.nl", 443, "dummy-key");
  assert(length == std::strlen(out.data()));
  assert(std::strlen(scratch.data()) == 1886);
  std::string request(out.data());
  std::string target = "GET /api/v1/led-conditions?spotIds=" + std::string(scratch.data()) + " HTTP/1.0\r\n";
  assert(request.compare(0, target.size(), target) == 0);
  assert(request.find("\r\nHost: api.kustgloed.nl:443\r\n") != std::string::npos);
  assert(request.find("\r\nAuthorization: Bearer dummy-key\r\n") != std::string::npos);
  assert(request.find("\r\nAccept-Encoding: identity\r\n") != std::string::npos);
  assert(request.find("\r\nConnection: close\r\n\r\n") == request.size() - 23);
  assert(request.find(ids[50]) != std::string::npos && request.find(ids[50] + ",") == std::string::npos);
  // Widest host and key still fit; one byte less of either buffer refuses the request.
  const std::string host(KiteWindDisplay::MAX_HOST_LENGTH, 'h'), key(KiteWindDisplay::MAX_KEY_LENGTH, 'k');
  length = buildRequest(out.data(), out.size(), scratch.data(), scratch.size(), pointers, MAX_SPOTS, host.c_str(), 65535, key.c_str(), Framing::Http11KeepAlive);
  assert(length + 1 == KiteWindDisplay::requestBytes(MAX_SPOTS) && length < out.size());
  assert(!buildRequest(out.data(), length, scratch.data(), scratch.size(), pointers, MAX_SPOTS, host.c_str(), 65535, key.c_str(), Framing::Http11KeepAlive));
  assert(buildRequest(out.data(), length + 1, scratch.data(), scratch.size(), pointers, MAX_SPOTS, host.c_str(), 65535, key.c_str(), Framing::Http11KeepAlive));
  assert(!buildRequest(out.data(), out.size(), scratch.data(), 1886, pointers, MAX_SPOTS, "h", 1, "k"));
  assert(buildRequest(out.data(), out.size(), scratch.data(), 1887, pointers, MAX_SPOTS, "h", 1, "k"));
  assert(!buildRequest(out.data(), out.size(), scratch.data(), scratch.size(), pointers, 0, "h", 1, "k"));
  // Four-spot LAN batch fits the small buffers.
  std::vector<char> small(KiteWindDisplay::requestCapacity(4));
  assert(buildRequest(small.data(), small.size(), scratch.data(), scratch.size(), pointers, 4, host.c_str(), 65535, key.c_str(), Framing::Http11KeepAlive));
}

static bool head(const std::string& text, Head& out) {
  std::vector<char> buffer(text.begin(), text.end());
  buffer.push_back('\0');
  static std::vector<char> keep;
  keep = buffer;
  return parseHead(keep.data(), text.size(), out);
}

static void testHead() {
  Head h;
  assert(head("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 2\r\n\r\n{}", h));
  assert(h.status == 200 && h.bodyLength == 2 && !std::strcmp(h.body, "{}"));
  assert(head("HTTP/1.0 200 \r\n\r\n{}", h) && h.bodyLength == 2);   // no headers, empty reason
  assert(head("HTTP/1.1 200\r\nX: y\r\n\r\n{}", h));                  // reason omitted
  assert(head("HTTP/1.1 200 OK\r\ncontent-length:  2 \r\n\r\n{}", h)); // case and whitespace
  assert(head("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nContent-Length: 2\r\n\r\n{}", h));
  assert(head("HTTP/1.1 401 Unauthorized\r\nContent-Length: 0\r\n\r\n", h) && h.status == 401 && h.bodyLength == 0);
  assert(head("HTTP/1.1 302 Found\r\nLocation: https://evil.example/\r\n\r\n", h) && httpError(h.status) == Error::Api);
  // Framing failures: length mismatch, chunking, truncated head, bad status line, embedded NUL.
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 1\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nContent-Length: 3\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: -2\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 2x\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 1234567890\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length:\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n2\r\n{}\r\n0\r\n\r\n", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 2\r\n", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r", h));
  assert(!head("HTTP/2 200 OK\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 20x OK\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 2000 OK\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nBroken header\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\n: empty\r\n\r\n{}", h));
  // Whitespace around header names cannot hide framing headers.
  assert(!head("HTTP/1.1 200 OK\r\n Transfer-Encoding: chunked\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nTransfer-Encoding : chunked\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\n\tContent-Length: 9\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nContent-Length\t: 9\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nX: a\r\n folded\r\n\r\n{}", h));
  // LF-only and bare-CR framing are rejected.
  assert(!head("HTTP/1.1 200 OK\n\n{}", h));
  assert(!head("HTTP/1.1 200 OK\nContent-Length: 2\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nX: a\nY: b\r\n\r\n{}", h));
  assert(!head("HTTP/1.1 200 OK\r\nX: a\rY: b\r\n\r\n{}", h));
  assert(head("HTTP/1.1 200 OK\r\nX: a\r\n\r\n{\n}", h)); // body bytes are not framing
  assert(!head(std::string("HTTP/1.1 200 OK\r\n\r\n{\0}", 22), h));
  assert(!head(std::string("HTTP/1.1 200 OK\r\nX: \0\r\n\r\n{}", 27), h));
  assert(!head("", h) && !head("HTTP/1.1 200", h));
  char unterminated[] = "HTTP/1.1 200 OK\r\n\r\n{}x";
  assert(!parseHead(unterminated, sizeof(unterminated) - 2, h));
}

static void testErrors() {
  assert(httpError(200) == Error::None);
  assert(httpError(401) == Error::Authentication && httpError(403) == Error::Authentication);
  assert(httpError(404) == Error::UnknownSpot && httpError(400) == Error::BadRequest);
  assert(httpError(500) == Error::ServerFailure && httpError(503) == Error::ServerFailure);
  assert(httpError(301) == Error::Api && httpError(204) == Error::Api && httpError(418) == Error::Api);
  assert(connectError(TLS_CERT_VERIFY_FAILED) == Error::TlsVerify && static_cast<int>(Error::TlsVerify) == 12);
  assert(connectError(-1) == Error::ServerUnavailable && connectError(0) == Error::ServerUnavailable);
  assert(connectError(-0x7280) == Error::ServerUnavailable); // other mbedTLS failure
  assert(KiteWindStatus::blinkOn(Error::TlsVerify, 0) && !KiteWindStatus::blinkOn(Error::None, 0));
}

static void testClock() {
  const uint32_t now = 1795000000; // 2026-11-18
  // Cold boot: no NTP yet, system clock at 1970.
  assert(!clockUsable(0, 0, 5) && !clockNeedsSync(0, 0, 5));
  assert(!clockUsable(NTP_TIME_SOURCE - 1, now, now) && !clockNeedsSync(110, now, 5)); // UDP NTP is not enough
  // Late NTP sync: Toki is valid, the system clock is not; sync is required, then usable.
  assert(clockNeedsSync(NTP_TIME_SOURCE, now, 5) && !clockUsable(NTP_TIME_SOURCE, now, 5));
  assert(!clockNeedsSync(NTP_TIME_SOURCE, now, now) && clockUsable(NTP_TIME_SOURCE, now, now));
  // Drift within tolerance is accepted; beyond it requires a resync.
  assert(clockUsable(NTP_TIME_SOURCE, now, now + CLOCK_TOLERANCE_S) && !clockNeedsSync(170, now, now - CLOCK_TOLERANCE_S));
  assert(!clockUsable(NTP_TIME_SOURCE, now, now + CLOCK_TOLERANCE_S + 1) && clockNeedsSync(NTP_TIME_SOURCE, now, now - 61));
  // A bogus NTP year never drives the system clock.
  assert(!clockNeedsSync(NTP_TIME_SOURCE, 1000, 5) && !clockUsable(NTP_TIME_SOURCE, 1000, 1000));
  assert(!clockUsable(NTP_TIME_SOURCE, now, -1) && clockNeedsSync(NTP_TIME_SOURCE, now, -1));
}

static void testSchedule() {
  Schedule s;
  s.reset(0xfffff000u);
  assert(s.due(0xfffff000u));
  s.succeeded(0xfffff000u);
  assert(!s.due(0xfffff000u + 599999u) && s.due(0xfffff000u + 600000u)); // ten minutes, across rollover
  const uint32_t delays[] = {30000, 60000, 120000, 300000, 300000};
  for (uint32_t d : delays) {
    s.failed(0x00001000u);
    assert(s.delay == d && !s.due(0x00001000u + d - 1) && s.due(0x00001000u + d));
  }
  // 401 waits ten minutes without counting a failure; the next transient failure waits 30 s.
  s.reset(5);
  s.unauthorized(5);
  assert(s.delay == 600000 && s.failures == 0 && !s.due(5 + 599999) && s.due(5 + 600000));
  s.failed(6);
  assert(s.failures == 1 && s.delay == 30000);
  // 403 is an ordinary HTTP failure with normal backoff.
  s.reset(7);
  assert(httpError(403) == Error::Authentication);
  s.failed(7);
  assert(s.delay == 30000);
  s.failed(8);
  assert(s.delay == 60000);
  s.reset(7);
  assert(s.failures == 0 && s.due(7));
  s.failures = KiteWindPoll::FAILURE_CAP;
  s.failed(9);
  assert(s.failures == KiteWindPoll::FAILURE_CAP && s.delay == 300000);
  s.succeeded(10);
  assert(s.failures == 0);
}

// Acceptance deadline boundary, including millis() rollover.
static void testDeadline() {
  assert(!pastDeadline(0, 19999) && pastDeadline(0, 20000) && pastDeadline(0, 20001));
  const uint32_t start = 0xffffc000u; // 20 s later wraps past zero
  assert(!pastDeadline(start, start + 19999u) && pastDeadline(start, start + 20000u));
  assert(static_cast<uint32_t>(start + 20000u) < start);
  assert(!pastDeadline(start, start));
}

// Multi-batch cycle age cap, including millis() rollover.
static void testCycleExpired() {
  assert(!cycleExpired(0, CYCLE_DEADLINE_MS - 1) && cycleExpired(0, CYCLE_DEADLINE_MS) && cycleExpired(0, CYCLE_DEADLINE_MS + 1));
  const uint32_t start = 0xffff8000u; // 60 s later wraps past zero
  assert(!cycleExpired(start, start) && !cycleExpired(start, start + CYCLE_DEADLINE_MS - 1));
  assert(cycleExpired(start, start + CYCLE_DEADLINE_MS) && static_cast<uint32_t>(start + CYCLE_DEADLINE_MS) < start);
  assert(CYCLE_DEADLINE_MS > DEADLINE_MS);
}

static void testHold() {
  bool held = true;
  const uint32_t last = 0xfffff000u;
  assert(!expireHeld(held, last, last + KiteWindPoll::HOLD_MS - 1, KiteWindPoll::HOLD_MS) && held);
  assert(expireHeld(held, last, last + KiteWindPoll::HOLD_MS, KiteWindPoll::HOLD_MS) && !held);
  // After the flag clears, a full millis() wrap back to the same age never revives the result.
  assert(!expireHeld(held, last, last + 1, KiteWindPoll::HOLD_MS) && !held);
  held = true;
  assert(!expireHeld(held, 0, 59999, 60000) && expireHeld(held, 0, 60000, 60000)); // LAN stale threshold
}

static void testFraming() {
  // Non-worker targets and single-batch cycles stay close-delimited HTTP/1.0.
  assert(framingFor(false, 0, 4, 51) == Framing::Http10Close);
  assert(framingFor(true, 0, 51, 51) == Framing::Http10Close);
  assert(framingFor(true, 0, 4, 4) == Framing::Http10Close);
  // Multi-batch worker cycle: keep-alive until the last batch, which closes.
  assert(framingFor(true, 0, 4, 51) == Framing::Http11KeepAlive);
  assert(framingFor(true, 44, 4, 51) == Framing::Http11KeepAlive);
  assert(framingFor(true, 48, 3, 51) == Framing::Http11Close);
}

static void testRequestFraming() {
  std::vector<std::string> ids = uuids(4);
  const char* pointers[4] = {ids[0].c_str(), ids[1].c_str(), ids[2].c_str(), ids[3].c_str()};
  std::vector<char> out(KiteWindDisplay::requestCapacity(4)), scratch(KiteWindDisplay::responseCapacity(4));
  assert(buildRequest(out.data(), out.size(), scratch.data(), scratch.size(), pointers, 4, "api.kustgloed.nl", 443, "k",
                      Framing::Http11KeepAlive));
  std::string keep(out.data());
  assert(keep.find(" HTTP/1.1\r\n") != std::string::npos);
  assert(keep.find("\r\nConnection: keep-alive\r\n\r\n") != std::string::npos);
  assert(buildRequest(out.data(), out.size(), scratch.data(), scratch.size(), pointers, 4, "api.kustgloed.nl", 443, "k",
                      Framing::Http11Close));
  std::string closing(out.data());
  assert(closing.find(" HTTP/1.1\r\n") != std::string::npos);
  assert(closing.find("\r\nConnection: close\r\n\r\n") != std::string::npos);
  assert(buildRequest(out.data(), out.size(), scratch.data(), scratch.size(), pointers, 4, "api.kustgloed.nl", 443, "k"));
  std::string legacy(out.data());
  assert(legacy.find(" HTTP/1.0\r\n") != std::string::npos);
  assert(legacy.find("\r\nConnection: close\r\n\r\n") != std::string::npos);
}

static void testResponseProgress() {
  const std::string head = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n";
  auto progress = [](const std::string& text) { return responseProgress(text.data(), text.size()); };
  assert(progress("HTTP/1.1 200 OK\r\nContent-Le") == Progress::Incomplete);
  assert(progress(head + "Content-Length: 5\r\n\r\n12") == Progress::Incomplete);
  assert(progress(head + "Content-Length: 5\r\n\r\n12345") == Progress::Complete);
  assert(progress(head + "content-length: 0\r\n\r\n") == Progress::Complete);
  assert(progress(head + "Content-Length: 5\r\n\r\n123456") == Progress::Invalid);      // extra bytes
  assert(progress(head + "Content-Length: 5\r\nContent-Length: 6\r\n\r\n") == Progress::Invalid);
  assert(progress(head + "Content-Length: 5\r\nContent-Length: 5\r\n\r\n12345") == Progress::Complete);
  assert(progress(head + "Content-Length: x\r\n\r\n") == Progress::Invalid);
  assert(progress(head + "Content-Length: 1234567890\r\n\r\n") == Progress::Invalid);   // more than nine digits
  assert(progress(head + "Transfer-Encoding: chunked\r\n\r\n5\r\n12345\r\n0\r\n\r\n") == Progress::Invalid);
  assert(progress(head + "\r\n12345") == Progress::Incomplete);                          // no length: read to close
  assert(progress("HTTP/1.1 200 OK\r\n\r\n") == Progress::Incomplete);
  assert(progress(head + "Content-Length: 999999999\r\n\r\n") == Progress::Incomplete);  // nine digits
  assert(progress(head + "Content-Length:\r\n\r\n") == Progress::Invalid);              // empty value
  assert(progress(head + "NoColonHeader\r\n\r\n") == Progress::Invalid);
  assert(progress(head + "Content-Length:  5 \r\n\r\n12345") == Progress::Complete);    // padded value
}

static void testHeapGuard() {
  assert(heapSufficient(MIN_FREE_HEAP_BYTES, MIN_LARGEST_BLOCK_BYTES));
  assert(!heapSufficient(MIN_FREE_HEAP_BYTES - 1, MIN_LARGEST_BLOCK_BYTES));
  assert(!heapSufficient(MIN_FREE_HEAP_BYTES, MIN_LARGEST_BLOCK_BYTES - 1));
}

static void testContinueCycle() {
  Schedule s;
  s.failed(1000);
  s.continueCycle(5000);
  assert(s.failures == 1 && s.delay == 0 && s.due(5000));
  s.failed(6000);
  assert(s.failures == 2 && s.delay == KiteWindPoll::retryDelayMs(2, false) && s.delay == 60000);
  s.succeeded(7000);
  assert(s.failures == 0);
  assert(!s.due(7000 + KiteWindPoll::POLL_INTERVAL_MS - 1) && s.due(7000 + KiteWindPoll::POLL_INTERVAL_MS));
}

